    while True:
        response = input(f"{Colors.CYAN}>{Colors.RESET} {prompt} [{default_str}]: ").strip().lower()
        if not response:
            return default
        if response in ('y', 'yes'):
            return True
        if response in ('n', 'no'):
            return False

